import React, { useState } from "react";
import api from "../api";

export default function Admissions(){
  const [form, setForm] = useState({ studentName:"", parentName:"", classApplied:"", age:"", phone:"", email:"", address:"" });
  const [status, setStatus] = useState("");

  const change = e => setForm(f=>({...f,[e.target.name]:e.target.value}));

  const submit = async (e) => {
    e.preventDefault();
    setStatus("Submitting...");
    try {
      await api.post("/admissions", form);
      setStatus("Application submitted.");
      setForm({ studentName:"", parentName:"", classApplied:"", age:"", phone:"", email:"", address:"" });
    } catch (err) {
      setStatus("Submission failed.");
    }
  };

  return (
    <div className="container card">
      <h2>Admissions</h2>
      <div className="two-col">
        <div className="left">
          <div className="box">
            <h3>Admissions</h3>
            <div className="rect-list">
              <div>Application Form</div>
              <div>Apply Online</div>
              <div>Fee Structure</div>
            </div>
          </div>
        </div>

        <div className="right">
          <h3>The Procedure</h3>
          <p>We appreciate your interest in us! ...</p>
          <form onSubmit={submit}>
            <input name="studentName" placeholder="Student Name" value={form.studentName} onChange={change} required/>
            <input name="parentName" placeholder="Parent Name" value={form.parentName} onChange={change}/>
            <input name="classApplied" placeholder="Class Applied" value={form.classApplied} onChange={change}/>
            <input name="phone" placeholder="Phone" value={form.phone} onChange={change}/>
            <input name="email" placeholder="Email" value={form.email} onChange={change}/>
            <textarea name="address" placeholder="Address" value={form.address} onChange={change}/>
            <button type="submit">Apply</button>
            <div>{status}</div>
          </form>
        </div>
      </div>
    </div>
  );
}
